406	export function calculateShannonEntropy(str: string): number {
407	  if (!str) return 0;
408	  const len = str.length;
409	  const frequencies = new Map<string, number>();
410	  for (let i = 0; i < len; i++) {
411	    const ch = str[i];
412	    frequencies.set(ch, (frequencies.get(ch) || 0) + 1);
413	  }
414	  let entropy = 0;
415	  for (const count of frequencies.values()) {
416	    const p = count / len;
417	    entropy -= p * Math.log2(p);
418	  }
419	  return entropy;
420	}
