588	function scanBase64Keys(text: string, budget: ExtensionBudget): Array<{ start: number; end: number; name: string }> {
589	  const found: Array<{ start: number; end: number; name: string }> = [];
590	  // Limitation: a key that starts inside a blob's window (no separator) can lose its extension once the rescan quota is spent; its plain key (20+ characters) is still redacted.
591	  const rescanBudget: ExtensionBudget = { left: RESCAN_QUOTA_FACTOR * MAX_EXTENSION };
592	  let scannedTo = 0;
593	  let rescanLeft = RESCAN_WORK_FACTOR * text.length;
594	  let from = 0;
595	  while (from < text.length) {
596	    const at = text.indexOf("sk-", from);
597	    if (at < 0) break;
598	    if (at > 0 && /\w/.test(text[at - 1])) {
