639	 * full stop where the entropy tokenizer trims it; an entropy token spans `sk-…/models` where the key pattern stops at
640	 * the "/". Redaction replaces by value, longest value first, so the enclosing value is replaced whole before a shorter
641	 * value inside it, and the shorter value is still replaced wherever else it occurs in the text. Resolution: an
642	 * uncertain (entropy) token that starts where a more confident match starts and extends past it is dropped (the token
643	 * `sk-…/models` loses to the key at its start, keeping the path). Every other match is kept, inner ones included:
644	 * an operator secret inside a key does not shorten the key (the key is longer), a key inside an uncertain token keeps
645	 * its deterministic classification for callers that refuse or redact only positive findings (the checkpoint guard,
646	 * path display), and a key inside a Bearer match is still redacted where it occurs again unmatched. The result has
647	 * one entry per distinct value, longest first.
648	 */
649	function resolveOverlaps(matches: PositionedMatch[]): ClassifiedSecret[] {
650	  const order = matches.map((_, i) => i).sort(
651	    (a, b) => matches[a].start - matches[b].start || matches[b].end - matches[a].end || a - b
652	  );
653	  const dropped = new Set<number>();
654	  let open: number[] = []; // earlier matches that reach the current position, so may contain the current one
655	  for (const i of order) {
656	    const { start, end, item } = matches[i];
657	    open = open.filter((j) => matches[j].end >= start);
658	    for (const j of open) {
659	      const enclosing = matches[j];
660	      if (
661	        enclosing.item.classificationType === "UNCERTAIN" && enclosing.start === start && enclosing.end >= end &&
662	        enclosing.item.confidence < item.confidence
663	      ) {
664	        dropped.add(j);
665	      }
666	    }
667	    open.push(i);
668	  }
669	  const seen = new Set<string>();
670	  const classified: ClassifiedSecret[] = [];
671	  matches.forEach((match, i) => {
672	    if (!dropped.has(i) && !seen.has(match.item.secret)) {
673	      seen.add(match.item.secret);
674	      classified.push(match.item);
675	    }
676	  });
677	  // Longest value first: a value that also occurs inside a longer one elsewhere is replaced after it, not through it.
678	  return classified.sort((a, b) => b.secret.length - a.secret.length);
