688	  if (/[+=]/.test(token)) return true;
689	  // A filesystem path (rooted, or with two or more separators) is not a credential even with a generated directory name;
690	  // a base64 secret that happens to contain slashes also carries "+" or "=", or has at most one.
691	  if (token.startsWith("/") || (token.match(/\//g)?.length ?? 0) >= 2) return false;
