721	  next: Map<number, number>; // node * radix + symbol -> child node
722	  fail: Int32Array;
723	  depth: Int32Array;
724	  output: Int32Array; // the value that ends at this node (the first in the list when values repeat)
725	  dictionary: Int32Array; // the nearest node on the fail chain where a value ends
