728	/**
729	 * Builds an Aho-Corasick automaton over the values. Transitions are keyed by node and by the index of the code unit in
730	 * the values' own alphabet, which keeps the keys small integers (fast Map lookups). Failure links are set in
731	 * breadth-first order (nodes sorted by depth), so a parent's link is set before its children's.
732	 */
733	function buildAutomaton(values: string[]): Automaton {
734	  const alphabet = new Int32Array(65536).fill(-1);
735	  let radix = 0;
