747	  const symbolOf = new Int32Array(capacity);
748	  const depth = new Int32Array(capacity);
749	  const fail = new Int32Array(capacity);
750	  const output = new Int32Array(capacity).fill(-1);
751	  const dictionary = new Int32Array(capacity).fill(-1);
