753	  let maxDepth = 0;
754	  values.forEach((value, index) => {
755	    if (!value) return;
756	    let node = 0;
757	    for (let i = 0; i < value.length; i++) {
758	      const symbol = alphabet[value.charCodeAt(i)];
759	      let child = next.get(node * radix + symbol);
760	      if (child === undefined) {
761	        child = nodes++;
762	        next.set(node * radix + symbol, child);
763	        parent[child] = node;
764	        symbolOf[child] = symbol;
765	        depth[child] = depth[node] + 1;
