test("adversarial inputs finish within a time bound: long runs of sk-, escapes, dots and chained keys", () => {
  const long = "REDACTED";
  const inputs = [
    "sk-" + "%2F".repeat(60000),
    "sk-" + "%252F".repeat(30000) + ".",
    "sk-a.".repeat(40000),
    "sk-" + "Ab1.".repeat(40000),
    "sk-sk-".repeat(30000) + "∕".repeat(1000),
    long + ".".repeat(80000) + long,
    (long + ".").repeat(4000),
