  const target = `${tok("z")}.Mn5Qr7Vw0${".Mn5Qr7Vw2".repeat(24)}`; // a tail longer than what the block leaves of the quota
  const input = `${block} then ${target} end sk-ant-${"REDACTED".repeat(2)}`;
